WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (519::BIGINT, 'Es un viejo verde, tiene favoritismo a las mujeres. No explica bien, sí o sí se tiene que estudiar por aparte.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-08-11T00:00:00+00:00'::TIMESTAMPTZ, '90bac641adde363b8ae49c95f4db33dbc109bf5d5f6be9368e84ec89d3e91629'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'He tomado tres cursos con él y por no haber podido llevar más, explica todos los temas de forma bastante práctica y sencilla, ejemplifica y hace ejercicios como loco, explica y resuelve dudas de clase siempre, califica suave y hasta le suelta pistas en quices o lo corrige, buena nota y buen profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-04T00:00:00+00:00'::TIMESTAMPTZ, 'b64f1b3c1134818402cad6e0adad9cf97b0f9416b028b0ee8eba59677f6ecc8e'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Explica demasiado rápido, tarde demasiado en calificar todo, lo veo como buena opción si esta repitiendo el curso, es un profe que hay que saber llegarle, no es ni el peor ni el mejor prepárese para hacer quices todas las semanas, la asistente es una inútil e inconsciente.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-31T00:00:00+00:00'::TIMESTAMPTZ, '0c2420bbd0d398113ec61fa15b938dfe6dd087cb654f7246b600ca67ec62871d'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'A veces las explicaciones suelen ser muy rápidas. Las presentaciones suele saltar pasos, por lo que se recomienda tomar apuntes en clase. Brinda mucho material de apoyo como folletos y videos. Tal vez, es el curso de matemáticas más interesante, porque se estudian aplicaciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'd2cef0a02fc1dc7af08b6cc0fce99de957b61191dc02e3b06cc9893d464e7987'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Las clases son un bostezo y siempre llega con sueño. No se aprende nada porque explica con pereza y califica muy pesado. Anda detrás de las guilas. Ni lo haga mae'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '0ebced45ad888cb3c2a3240f0a8e6468a4dfd30fb3f64dbd751101e797b605e4'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Tiene una metodología basada en la exposición de filminas en las que tiene el material, sin embargo, lo explica, repite el procedimiento entero paso a paso para que quede claro y resuelve todas las dudas que se tienen, puede ser un poco odioso al responder, pero ayuda montones al evaluar.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-04-04T00:00:00+00:00'::TIMESTAMPTZ, 'd062893dcbe4877a6cd4c6a1a82b4365c81809c53c2d02265be264b9df2ea2a0'::TEXT, ARRAY[563, 634]::BIGINT[]),
    (519::BIGINT, 'Muy buen profesor para el curso, lo hace muy llevadero para ser un curso de verano. Intenta que todos los estudiantes pasen el curso, pone ejercicios parecidos a la práctica en el examen, califica suave.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'f0035880e304c29ea7340a3b1dfb4a10d3fb5222f3a22f5ab5137c3c0aef0e5f'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Califica medio raro y puede que sus clases sean algo "aburridas" pero la verdad si intenta de simplificar la materia para que uno entienda. eso si, esto es matematica entonces al final del dia la diferencia la hace la practica.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'a716027f1ef02d44e7c90429e5d0790a7912023a70bb5d14731169e120bd03e9'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Califica duro y no da buena retroalimentación en la revisión de los exámenes, espera que usemos el método que el quiere y si no usa dicho método penaliza pts.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2026-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e5caecb78cebcf2345f262e2a2f9ff8ceadc4bf266912f6ad5e8fb3d9360fe8b'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Explíca muy bien y está dispuesto a ayudar siempre (hasta repone quices). Hace repasos antes del examen. Pone muchos quices y tarea (iguales a los ejercicios de clase) por lo que se puede levantar muy bien la nota. Con ir a clases y al dia se pasa bien. NO hace distinción entre hombres y mujeres.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2025-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'e4f5024be2f8cf8d04160019605a43c4d71b5669c4f370606f69dc7f5b62058c'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'El profesor no explica casi nada de este curso, en lo personal, sentí que solo llegaba a apuntar cosas en la pizarra sin explicaciones muy claras. El curso en general es difícil si usted no tiene buenas bases de CDI. Deja quices CASI todas las semanas o cada 15 días.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '150bfc19794325a8dbef349c1dde405cd4afc39b49d9b974411ac3043d0eff51'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Si usted lleva tiempo sin estudiar mate tiene que ponerle, se entiende que ya usted viene con ciertas destrezas para resolver algunos problemas complejos, el profe vacila y en ocasiones espera que ya uno sepa como resolver las cosas por ser el primer curso de mate. Si es viejo verde y liguista'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases largas']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '6699b71ad07cd6792a491ac8599f42977cfb740e515f98e76523fa1c2e0f6d1d'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'El profe es muy bueno para el curso. Explica súper claro y conciso, hace que todo se vea sencillo y no busca confundir con la materia, va directo a los pasos a seguir. Si participa en clase, presta atención y hace las tareas que ponga, de fijo pasa el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'a10755b3e66a8f041ce4d573779d2090b2eedcf6ad2a78850e2d7cd7eef8554b'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'De los peores profesores. Si tiene la oportunidad de llevar con él, desaprovéchela. Cualquier comentario que diga que el mae es un viejo verde es cierto. Si usted es mujer y se le hace bonita al mae, fijo pasa. Basta con ir a consulta a solas con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, '8d00218e989001ff55b6c957667fea91b62a52e8cfa5c52c4e7e2ff1a5e846ad'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Excelente profesor. Se ve planea muy bien sus clases. Combina muy bien la teoria con ejecicios y práctica. Tiende a dejar muchos quices y tareas pero sirven para llevar materia casi al día. Sus explicaciones son claras, prácticas y concisas. Se procupa por estudiante aprenda repite si no queda algo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2025-10-28T00:00:00+00:00'::TIMESTAMPTZ, '87c0e9ca5c2dd507dc646dbde971f7f3b26c122e0bb6e654ab4c93de4c39ffbd'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Realmente es un buen profesor lo recomiendo bastante si es tu primera vez llevando el curso, el único detalle es que se confunde a veces con los datos pero lo procedimientos son claros y si no entiendes vuelve a explicar'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-10-18T00:00:00+00:00'::TIMESTAMPTZ, '38918453e9a0250d47ae5514cba5e681780f6aae8d68d60db3e9a3ff71d56a13'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'el profe no sirve, si tiene otra opción tómela'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-03T00:00:00+00:00'::TIMESTAMPTZ, '060c8041b2a4b4dba7beb1270a18d87a15dd8402e61fcd1a57c18dd61ed9adae'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Top profesores de la escuela de matemática, si ve curso con él llévelo, y no se deje llevar por la primera impresión, parecerá que tiene sueño, pero si participas el profe se anima más. No falte a sus clases o se pierde de los resúmenes de la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'c44a748d3b559c8af2c0e0bd99d3af294e531fc46727cffaecdb814600c20f6c'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Llevé el curso en verano y en general no me pareció mal profe, hace los examenes identicos a los ejercicios que nos manda entonces uno puede prepararse mejor'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-01-27T00:00:00+00:00'::TIMESTAMPTZ, '2a5c31444e9bd32823bef033594379d9658c7de525764d9eb2a80ab97ef6cbe8'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Al ser el coordinador de la cátedra, explica y pone mayor atención a los temas que realmente serán evaluados en lo exámenes, además brinda presentaciones por semana para estudiar. Hace bastantes evaluaciones, muchas de estas virtuales y/o grupales. No califica para nada duro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, '9c233a2ae225fc0588bcd5df208ed1124b14a801d2f54b61786a67b301ca5089'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'El profe da ejemplos como los del examen y enseña muy objetivamente (lo que no es importante lo omite). Está atento a brindar ayuda y califica como debe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '1138ef1231987a626b5a8edd5f40ec8d2479bedb1a18f5bbcd061cfcdfdb60b8'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Es un buen profe. Se preocupa porque los estudiantes aprendan y vuelve a explicar si usted pregunta. Los ejemplos de clase y los quices son con ejercicios tipo examen, así que uno va bien preparado. Super recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'fd21a28ec40861302e1a89527ca4591a8c6549cfbfb7ca0f217b1efbfce93417'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Da bastante bien las clases, a veces las da algo apresurado, pero no duda en repetir si alguien se queda atrás. Deja bastantes quices para hacer en casa, algunos hasta en grupo. En general ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Muchos exámenes']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'a2fbc681111061977e9b1189c76385144bc08f97a650ade14c7afccbc4a43623'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Explica excelente la materia, y califica muy suave los examenes, ahora mismo es el director de cátedra, entonces todos los ejercicios desde el primero que enseña en clase son muy similares a los que pone en los examenes'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'fefda137b27dd477d1fdd80af9399e0b92354ed14e52e141a16c88750aad0ed5'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'El profe es bueno, explica casi todos los temas bien, pero parece que le da pereza dar la clase. En general usted va a tener que ser muy autodidacta por qué las clases de el no son suficientes. Sin embargo es muy accesible con quices y evaluaciones, además califica suave y es una persona agradable.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '95932146159040e0f2758a21aceb75d7c8e02e9acfdda9db56cf206fdca9865e'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Legalmente ni pierda el tiempo con este mae, no le interesa lo más minimo que usted aprenda, el solo se la pasa saliendo del salon para andar con el telefono o cancela las clases para hacer virtuales de 30 minutos solo porque le da pereza ir hasta sj, si matriculo con el de ya el curso por perdido'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-03-23T00:00:00+00:00'::TIMESTAMPTZ, '7d040e7bc549e12961e5c6798b6b4aec0ae3040a11a75c4df97d26bef28d1d9f'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'El profesor explica demasiado claro, ayuda demasiado a los estudiantes, lo recomendaría para personas que llevan buenas bases, ya que no se detiene mucho en temas de cursos anteriores y se debe ser algo autodidacta.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'e912215415d8071a5ea9968f03c6373636541f855ebb9e1cc69030186f43bd88'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Explica muy bien y da mucho material de apoyo al estudiante. Quices un poco duros pero ayudan para prepararse en la materia. Paciente y muy didáctico.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2023-06-24T00:00:00+00:00'::TIMESTAMPTZ, '931f219f72f88ce352b434046845759aa5cdfa3b4bbd5f7d67ae683c1c6fe712'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'El profe es una teja. Se enreda un poquillo en los ejemplos de temas de matrices y vectores, pero nada del otro mundo. Suele ser muy claro e incluso puede que lo ayude a final de semestre con unos cuantos puntos de quices. Da mucho material de apoyo en sus presentaciones.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'a819441405e18b6348e2c2db4c68be5c6c757edc0e28ada4c2338c01d46e29c9'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Si usted no lleva buenas bases no lo recomiendo porque da la clase muy rápido. No le interesa ver pasos extra o profundizar, ve lo que importa en el examen. Deja tareas/quices súper similares al examen; es demasiado teja el profe. Si tiene dudas pregunte, siempre dispuesto a ayudar. Sabe muchísimo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, '682c670df9f1d6a6836536d2ff44bd6935292655bd17a6415cff316a37dbbf1d'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, '980c7ef64a8a25b00d49503a448c99faf8d1c639a44ebd1ca36ecd92f93e09da'::TEXT, ARRAY[923]::BIGINT[]),
    (519::BIGINT, 'El profesor es excelente, siempre dispuesto a ayudarle en lo que pueda sobre todo si usted va a consulta ,muestra interes y trabaja se pasa y no te deja solo con las consignas que a veces pueden ser muy crudas matematicamente pero el se lo simplifica y traduce al facil para que logres entenderlo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'd0fbf940e4d0669a48392e9406e86689ba37bbdc2c2676390c99138e6c42418d'::TEXT, ARRAY[923]::BIGINT[]),
    (519::BIGINT, 'PÉSIMO PÉSIMO PÉSIMO! Si quiere versela a palitos para aprender y pasar meta con este profe. No ayuda en nada. Da sólo 40 min de clase y se salta un montón de pasos. Los exámenes quiebran con este tipo de profe. QUIERASE Y NO META CON ÉL'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-22T00:00:00+00:00'::TIMESTAMPTZ, '63822c2b8e596d9c5630ccd86172f4fe34b95d65b43ac817fc20a79ab0a0755c'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'No se por que el cuenta con todas buenas recomendaciones. Realmente en virtualidad se ha acomodado demasiado a las consignas y solo da 40 min de clase a lo mucho. Los ejercicios que resuelve son buenos pero el explicando es pésimo, se brinca la mayor parte de pasos intermedios y solo medio explica'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2022-03-20T00:00:00+00:00'::TIMESTAMPTZ, '313355669fe4ad588297ecf748f9063384beae40b2bf46054a463372b7cd2a6a'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, '(Virtual) Explica muy bien y realiza ejemplos, aunque a veces va muy rápido. Los quices son difíciles pero preparan bien para los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '07c74573be83b139dda55e2823bd632fa8055485c9443cdd8acb01b409649cb5'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'En las explicaciones aveces suele enredarse un poco y de mi parte tuve que ver clases de otros profes para entender bien, insistió bastante con conectase sincrónicamente y hasta dió puntos extra en las clases, legalmente es pura vida, sus quiz eran 10 veces más difíciles que los parciales'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b737cc7a2699febbc8b3c8ac50ef04c8c386986e25c72d9919648fc6e9acc99d'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, '(Virtual) Sus clases son cortas y va al punto, es rápido explicando pero lo hace muy bien. No deja muchas tareas además de las impuestas por la catedra. Siempre está dispuesto a ayudar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'f4bf955280f228c208fb8e2137128b1a1240a1ce792f2ed2fc306788a2271049'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'explica muy rápido, como persona es super tuanis, y si le preguntas el siempre esta dispuesto a explicar, pero como profesor para primeros ingresos...mmm creo que no es el mejor... casi que la clase se da sola. igual tambien es el interes que muestres por el curso... ay que ponerle bastante.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-24T00:00:00+00:00'::TIMESTAMPTZ, '9055ff1c24bfa43afd4f2d7c35f0dccb6438e1c5893d51a9166e8e4dbca2fd3a'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'El profe no es el mejor, pero ayuda demasiado en las consultas y es tranquilo para explicar, en las tareas de cátedra me ayudó en las consultas entonces aprovéchelas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '275632e31fb44c1734051dd0b34b2f746ec0668bb8daaae968957ac4062ce2d4'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'No lo recomiendo, mejor busque otra opción.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, '1366d7ffda2d86a8454b4e35591ca7650a460f8ed4fe4d18f4724564918185fb'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (519::BIGINT, 'Se rige solo en lo que dictan las guias semanales por lo que si te cuesta algún tema es mejor que busques otra ayuda'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'b041f46411c032824ce1abf28f520ac12842dbe7c5ad98084c369b5a5f0c521f'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Sabe mucho y explica de forma resumida para resolver ejercicios al final, cosa que a mi me sirvió. No deja muchas tareas, solo los GAAP de la cátedra, los exámenes son fáciles y cortos, por lo que si fallas te baja mucho la nota. Sube las clases en carpetas ordenadas por parcial y es util.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, '13e2281a583e56ce355c6a74f6cc49cca5adcb3840fd0762f4f32b335fb9a1a7'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Norberto explica todo súper rápido, hay que prestarle atención si no quiere perderse, pero se le entiende y explica claro y al punto, es buen profe. Casi no deja quices, en todo el semestre hice 2 de él. Todos los demás quices y tareas son las que deja la cátedra.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '20db2fa4ff0f4d29928733955b06460d08876d67d6402577afcab8e15e3bb77c'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Es un profesor bastante promedio, no es bueno ni malo, pasar es fácil si uno se apoya en el material de cátedra y en las clases, pero no lo recomiendo si se pretende solo estudiar de sus clases.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '1f2db83e08a3fba412904a2b08e11252b0f8c2323e2981454eb832675af4a7c3'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'No lo recomiendo, explica ejercicios MUY diferentes a los exámenes o GAAPs que hace la Cátedra. Si se lleva con el a huevo tiene o que ir a tutorías a parte o ver mil vídeos en YT para ver si entiende la materia dada por la Cátedra, que es la que al final califica todo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-11T00:00:00+00:00'::TIMESTAMPTZ, 'e039909088e21d770143a5db9335813f73be8bb9d9bbc0be7ab2aac357c397ec'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'El profe explica excelente, el problema es que las clases son sumamente cortas y la mayor parte del se debe realizar estudio independiente. Con el tema de las evaluaciones es bastante complicado para lo que explica en clase, sin embargo si logra salir bien, el examen de cátedra es un queque.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '975ccfd69cc9cf7308459a870d7caa2a0537d78f11351bf24ca4f319b4661d2c'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Al menos en clases virtuales es un profesor súper promedio, a veces es grosero y chichoso. Las clases son cortas y explica muy por encima, y en consulta no ayuda mucho, pero ecua no es un curso difícil.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '6113e32ea8a5035de76eb91e946d872fde645c1d1e1a3d4b1a98e80d967761fd'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Las clases son cortas y explica por encima (o al menos así lo sentí). Hace uno que otro ejercicio en clase y para el resto, uno debe aprender a estudiar por su cuenta. Puede costar un poco que le responda las preguntas fuera de clase o fuera de las horas de consulta.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '411da188d709ce3061dd02045cf586efc5ac554f1a6112b9161d5cb68ec0ab4c'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Un ASCO es realmente malo, enseña pésimo no sabe ni el que explica o resuelve, no da clases que pasa cancelando y envía clases grabadas pésimas. En un curso de este estilo es una pesadilla, ya que los exámenes quiebran sino se estudia por aparte ya que no se le entiende nada. MEJOR NO LO HAGA'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '3cf1e728b8c4e839dc0e72a3f87599f130333dd0675cacb23208b7c20f366112'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Llevé el curso en modalidad virtual y honestamente no lo recomiendo. Fue muy vago. Las clases son cortas (50 min) y hace 3 ejemplos tipo kinder. Si no eres autodidacta tienes que sobrevivir con éxito académico y tutorías particulares. Tienes que profundizar el tema tú mismo ya que él no te explica.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'e7859cf3fcdc55f94f8325526f6efcd89edbb4f9486dc6c29956192fba7ef705'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Lo llevé virtual y no ayuda, solo responde mensajes si está en clase o consulta, aunque sea para algún reclamo o problema con el Tecdigital, sus clases son resolver 2 o 3 problemas, no explica teoría.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, '649a3452f33b756f2c66acd5c0ca50f1b55ab136010f909a20d8fd95d59fe275'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Explica muy bien, va al grano, lo hace rápido y claro. Las clases virtuales son cortas (50 min a 1 hora). Si tiene dudas las aclara sin ningún problema.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'e25553af0e84449ab7cf11c53118f51faecb3fbe120aaf69085b8837a1f5a134'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Buen profe pero para clases virtuales no lo recomiendo, sólo da uno o dos ejercicios y cierra la clase.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'dba023b7a23a22e66628eda97d7a49ab47bd5630f5c80cd87256d641f7c9e287'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'El profe, en este segundo semestre del 2020, fue muy vago; solo se enfocó en terminar rápidas las clases (40 min a 1 hora). Además, en cada tema, solía realizar 1 o 2 ejercicios. Hizo quices difíciles de resolver. No lo recomiendo para la modalidad virtual.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-19T00:00:00+00:00'::TIMESTAMPTZ, '305a23cfccd44e6246ac48769717e5bf415c6a43d02d0b0517382bb22d806244'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Muy buen profesor, explica bastante bien, contesta rápido si hay dudas, buena actitud, no califica muy duro, se adaptó muy bien a las clases virtuales, algunas evaluaciones pueden llegar a ser largas pero no imposibles.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'f5300c3a921e4bc0b7633b8ceb511a0a4452f41191f94faff8a1e9a0e33b46db'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'El profe es buena gente, explica bien y sin rodeos, da tips también. Pero si espera quices fáciles no se lo recomiendo, lo quices son a matar, asi que debe estudiar mucho, sin embargo eso es bueno para el examen porque se ven más fáciles.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '7de408d5110f3ddb75c22c27cd85a21776786c1048c159fcac26d7802d45cfb6'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'b8969166cacbf9477cb469103c2479d2579acf5285f908c4d400f56b7aa4c400'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Este sí es un profe de verdad, lo quiero mucho porque de veras es excelente'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'e5d36d603e04316a87628a076bfe78e1040f23a3513466133ff050a7877fba8a'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'El mae explica bien, va directo a lo que vinimos con fórmulas y ejercicios. Repite si es necesario, el curso es muy fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '316b28d5f38b1d6cf4c10c7a061677ac4c7fe724ac103291fd32482dcbb14501'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Explica toda la materia de una manera demasiado fácil y entendible, hace que el curso sea regalado (con el contra de que no entra en formalidades matemáticas). Es muy organizado con todo el material en el TecDigital, lo prepara bien a uno para los exámenes. Si hace las tareas pasa cagado de risa.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2020-01-08T00:00:00+00:00'::TIMESTAMPTZ, '30145658a4878ec6ca6a831a66e9432d1e0532c380b46941d6327136bc726e14'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Es super organizado y explica muy bien, deja bastantes tareas y quizzes por TECDigital pero eso ayuda demasiado, uno con hacerlos ya va preparado para el examen, califica suave. Muy Pura vida'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-06T00:00:00+00:00'::TIMESTAMPTZ, 'a45049e52dc5bcd4f98125dde23b3d3a130c8f3a65b99ea8d0aaae6a618e1cb3'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Explica la materia bastante bien. El curso es semivirtual pero los materiales virtuales están bien preparados. Con poner atención en clase y hacer las clases virtuales está sobrado para el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'efc86fcee71b85b7676593e9a58236be16ce8067b31e5661f53605293a6d2d7d'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2019-11-20T00:00:00+00:00'::TIMESTAMPTZ, '45371e89977c3278437e7b49d6df28e68ce0ab322b9eee1a31a8aa5b55874202'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'En ecuaciones diferenciales curso semivirtual, se nota la organización y preparación de sus clases tiene todo muy organizado en tec digital en donde muestra materiales de apoyo para estos cursos semivirtuales, como material escrito, vídeos, aplicaciones CDF que ayudan bastante. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2019-09-15T00:00:00+00:00'::TIMESTAMPTZ, 'b6b69fb980a491e03f073b2c246cdd5976daa2662d974a6ae614e59bbcbf0159'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'He llevado varios cursos con él, antes le ponía más a clase y hacía prácticas para examen. Ahora solo proyecta el libro y hace los ejercicios del libro, para eso mejor leer del libro y no ir a clases... Siempre ayuda si se le pregunta, califica justamente y es flexible con las fechas de los quices.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2019-08-12T00:00:00+00:00'::TIMESTAMPTZ, 'd9a251c3dc456ea58e6314255ce28a607eaf8741bbd02c228d000c3acc98c16b'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Muy buen profe! Explica bien. Puede ser aburrido porque proyecta la materia en la pizarra pero se aprende. Los quices son un poco mas difíciles que la materia vista en clases. Califica suave y es amable. Eso sí, algunas veces alza el tono de voz cuando explica y uno se asusta jaja'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'e66f04faff0d30bb14d817ff15584b36c76f1a2ea6d74576cd888a9268af6e9d'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Se tiene que estudiar mucho por cuenta propia ya que los ejercicios que el explica en clase son muy pocos y además lo que hace es leer las presentaciones que se suben al TEC-Digital'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2019-07-20T00:00:00+00:00'::TIMESTAMPTZ, '1f1c6083fef3daa60e30b4ae31b8cf91a62c765b3cc516e1b7d693e685ce3a63'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Es buen profe y explica únicamente lo que tiene que explicar, no se anda con rodeos. El punto negativo es que no explica los rubros de evaluación claramente.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b543c9c8a86851c0d5c4b4771711d8ab00d1282bede606ff64a37e7856731b54'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Es buen profe, pero explica muy rápido y hay que estudiar todo por cuenta propia. Deja trabajos y quices para la casa enormes pero que lo preparan excelente para el examen. Los ejercicios que se resuelven son de un nivel muy superior al examen. Tiende a ser aburrido pero ayuda bastante por whats.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2019-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'f07b0ba51b67b6ae3cfb67afa8544acee36fdff6e37496d2796484b66b393154'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Es buen profe y muy pura vida, pero las clases son súper aburridas y además los quices son muuuy rudos y la manera de explicar es leer el folleto. En el segundo examen me calificó muy rudo y en el último mágicamente me calificó muy suave. Eso es buena señal, fijo el mae al final ayuda bastante.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '1b0f04158292a81d561e5cf04944dbf44bd2c56dbefbcd2e5c06a3f52f284e27'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Excelente profesor, sus clases son muy claras, recomendado para llevar verano!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2019-01-21T00:00:00+00:00'::TIMESTAMPTZ, '47c1089effdf934a1aa1135720233523a072980f5f173a930780d4d06857e1ad'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Buen profesor pero su método no es bonito. Solo proyecta el texto y explica a partir de él, por lo que la clase se hace demasiado aburrida. Califica exámenes suave pero los quices son bien difíciles. Tiene que llevar la materia al día para pasar bien. Si va raspando él le ayuda.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Da crédito extra']::TEXT[], '2018-12-29T00:00:00+00:00'::TIMESTAMPTZ, '97bceb36d5c5a6dd67ed92dbf68a9c2eed4370373ea589ebd321aa69c8a4c8ac'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Es buen profe pero hay que ser autodidacta porque sus explicaciones consisten en proyectar y leer los ejercicios que ya están hechos en los folletos de la cátedra. Quices difíciles, pero califica demasiado bonito los exámenes'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '1b1f892550e855b1b493263e6f6e2e1f01bb60527b7c6ba49411901a8c98b99c'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Sus clases son ir a proyectar lo que está como material de apoyo en el tec digital, no es mal profe pero es DEMASIADO aburrido'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '449b500c82bd1b89ff23748da352124fe7018605a2db283959baf51b8132718c'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Llego como sustituto a medio semestre porque el profe anterior se pensionó. Muy bueno, explica con claridad, la clase se hace un poco aburrida pero nada de otro mundo. Hace quices demasiado rudos, si no estudia mucho no espere que le vaya bien en los quices'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'bf7ebb5631ccc63df91961ea3ae84618d5678d9fbd8e06dbe3c5e14d08f7c6c6'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'Super buen profe, lo malo es que discreta en sí es ruda, pero él es la leche!'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-29T00:00:00+00:00'::TIMESTAMPTZ, 'fbb9be46b06cd62d4ded589796bf7cdc5db3029193ca1ee1335ff3ac839a42a2'::TEXT, ARRAY[1018]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'ea63435749dbd2535a86f349014dcc0f76b7c037c8c0f77ff64500bac4a429c2'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Esta entre los mejores profes de mate que he tenido, recomendado. Recomiendo hacer todas las tareas y con detalle.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'cbe0763b62472aa6078cc5c836e590379b71a96c9cf3d88381355149cf3a1836'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Excelente profe...Pero debe ir a clases y hacer las tareas para que le vaya super bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-14T00:00:00+00:00'::TIMESTAMPTZ, '662a799ea907fd1d93b45f947126c0b6fdaa976d2162ca5ff5f4664257a5eb9b'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'El profe es súper buena nota, hace las clases cortas, da lo necesario para pegar teja en lo exámenes y hace que el curso valga máximo 2 créditos. Súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-07T00:00:00+00:00'::TIMESTAMPTZ, '185b6291e2250875ff235162386dbda1ce2390b6478a7a4e4afaddb5e7cdd532'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Explica lo necesario para ingeniería. Califica tuanis.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, '88e471a39980212ce981bb225b0c61799974af56507810402e3ef4b6f3f56ba9'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Generalmente la clase terminaba temprano, pero aún así veíamos todo lo necesario y lo explicaba bien, además evacuaba cualquier duda con paciencia. Se asegura de dejar claro todo lo que entra en el examen. Muy comprensible al calificar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '4aba939324bc3b77c0eb066a99c5530a4a3d799d5417c6f0962df1d9c289039e'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'El profe es muy atarantado a la hora de dar la clase, pero prácticamente se le da a uno la materia en bandeja de plata. Para las prácticas sí hay que rogarle por ayuda si no pudo hacer un ejercicio. Lo mejor es que hace una práctica para el examen que es prácticamente TODO el examen!'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '3d20057c125904209e60c901a12c6bed8d2f946fc70632930871a98159ad3827'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Lleve el curso semivirtual el semestre pasado,era solo una clase presencial a la semana entonces explicaba bastante rapido, pero hace un buen resumen de la materia y explica solo lo que entra en el examen de manera clara. Deja tareas casi todas las semanas entonces hay que organizarse bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'f66ec31ea03928117b214a0004a7f0911ef08a0cf11eccea7bc3c6777b66f148'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-13T00:00:00+00:00'::TIMESTAMPTZ, '7411d238bace1edae09974071d08462c36182ed8be186402562b84be0496f006'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Yo lo llevé semivirtual con él y pues me parece que da una buena guía para estudiar (Tareas Virtuales Obligatorias), pero como da la mitad de clases presenciales no puede explicarse muy bien y va muy rápido. Aún así el curso no es muy demandante y califica muy suave así que dele con él sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'a767d3ac6687993c42442995bf0ff6b49355d559da2bbc7e7cc8e292dd46d292'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Demasiado tuanis, un profe recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2017-10-09T00:00:00+00:00'::TIMESTAMPTZ, '859af448db85929855fae64c9b7fc7a3152254242f8bcf0e2766569c83146271'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (519::BIGINT, 'Explica muy bien y da suficientes ejemplos'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '62eaede454afe6d15e28d8988bb0a91aaa13af0bc94119ffb0f6145144e0b16e'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7cb29b572164cc80728a3f0bee529e9619a55a6ba69824ce7e2356341701ed52'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '90d316e4bdeadea237cafa74e444758f6a20b0dd1c551a3d1538ebb8ca411839'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Excelente profesor, se aprende bastante y califica justo. hace muchos ejemplos en clase que sirven mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '7fec17ee0ce0369e91dc67ad900cbaa8e4be2a2ad30c1e271d23889c7a287af0'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Califica súper suave, ayuda un montón, se sale de clases temprano, es buena nota.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9f56deb39228314a8756f994980ec611b006d60da11ee5a6448bcfd3b6dd9398'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Su clase es super fácil, ayuda un monto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'dd9095ebbd010b40a8f655e067417cf164384977b176c94c08b3f02c8b6056a2'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '9d6f4bc76ed5fd5fe7dbd6562290bd70e4ba38b1d476925087621b181806fbbc'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Clase facil. Si matriculan con el mate van a pasar, pero no van a aprender y creanme que se necesita aprender para proximos cursos'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'ded15c7ccc0cd6fffa09a453ed62de592adc6498461c8379859f45f4788f6164'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Excelente profe! No necesita las 3hrs para dejar clara la materia, y explica super bien en 1hr de clase. Lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'edab16925570d28cd40e2d00efe2580b4dcfef82305a9ceedab714aa09d34e52'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Explica lo normal como para pasar el curso , califica normal , quices muy difíciles,'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, '7065ba934da0f1da2d2dcebf1a44438f735ee2fa5b80db70f2bb4b1875315919'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'El mae es muy buena gente y es relajado. Brinda ayuda si se le pide pero por lo general explica excelente. Muy buen profe, eso si los quices algo rudos pero califica bien'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-14T00:00:00+00:00'::TIMESTAMPTZ, 'd8b38564346599a7a241465ed1a74828f1a82fa2b869b81ac21c1bb9022374ad'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Para ED es excelente. Va rápido, pero si se acostumbra pasa con buena nota. Permite salir bien al principio y relajarse al final. Muy buena gente, atiende dudas, pone varias tareas fáciles. aunque los quices son durillos. Si va a clases y pone atención, pasa sobrado. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2016-12-10T00:00:00+00:00'::TIMESTAMPTZ, '68f0744be47efa32cc7572a41f0c87318237962846c0850bb5b38100739c6607'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'No entiendo por qué Norberto tiene una calificación tan alta... cuesta mucho entenderle, es demasiado vago.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'f4953ac4587515270ee834e8419223920d67ef622fba730d8d0ae14f451f92c1'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (519::BIGINT, 'Muy flexible, casi no hace quices y en los examenes reconoce el procedimiento. En lo personal, muy buen profe. Explica bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'd5b98f0eb6a2d61ae3251b8ff8f77bb889febb0088cb80d8f9288a5dc336787f'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'De los mejores profesores, explica demasiado bien y califica de manera muy justa. Súper Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5bdbf3347d10b6ba994923730a52c66da9b15a534e767d127b2e8ce27cfd93d2'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Hace que el curso no sea tan pesado, explica muy bien la materia y califica justo. Bastante recomendado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-26T00:00:00+00:00'::TIMESTAMPTZ, '553154a0725a74b03f529a57ba2f84c465a2025a0f711c81b0fb0f0223ea5525'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Excelente profesor. Muy flexible y no es malintencionado con el estudiante. Reconoce procedimiento y es muy pura vida. Es muy bueno explicando.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-25T00:00:00+00:00'::TIMESTAMPTZ, '10ecd5b8809fb9957e1a0f67f25bbb8b3b8541706a16518eb9e92ce724dc051a'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Muy cómico, las clases son súper cortas. Califica suave'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'b314cb78abbec9b57d6a26550294668e7f3070e4f45b9a6573c4f4b3ac6066a2'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Él es muy buen profesor. Tanto que con 1 hora de clases le basta para que quede clara la materia. Es un personaje en sí. A veces (muy rara vez) se enreda con lo que hace, pero esas ocasiones son las mejores porque él las aprovecha para explica errores que no se deben cometer. CRACK.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'dbac291acf7b0f4c20d919ae5c047428dbffc156a63a1c5fd971f149a4c5be99'::TEXT, ARRAY[605]::BIGINT[]),
    (519::BIGINT, 'Ya he llevado varios cursos con él. Muy tuanis, hace las clases entretenidas y explica lo necesario. No le gusta hacer clases muy largas y es muy flexible tanto a la hora de evaluar tareas o quices o al calificar exámenes. Totalmente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-20T00:00:00+00:00'::TIMESTAMPTZ, '2d26d188115e6d4b3b608523c44115afc097bb0dec5baf561fff04d324c781ff'::TEXT, ARRAY[935]::BIGINT[]),
    (519::BIGINT, 'Excelente profesor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'dbac2a8838e1f70a08ba04c918bb04747de3fe06f9bdf499375500d6d8c91f45'::TEXT, ARRAY[923, 2444, 634]::BIGINT[]),
    (519::BIGINT, 'Resumido: Crack! Detallado: muy tuanis, con humor, no es de leer diapositivas. Da lo que se va a calificar en el examen. Todo la materia la escribe en la pizarra, explica bien con ejemplos para que usted entienda. Quices como cada 15 días, explica tan bien que para el examen casi ni hay que estudiar'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'd10170168e65892912c48dc08d3590c8d186fca6b914054be883c9e795d14c8b'::TEXT, ARRAY[2920]::BIGINT[]),
    (519::BIGINT, 'Buen profe, super claro y lo prepara bien para los exámenes. Las clases no las hace muy largas. Muy recomendad'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '7d3c4465ef309ec4630a68a1b6defe88b656ee436e8e5e45758cbd8b9196faa8'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'El va a lo que va, enseña todo lo que entra en el examen. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, '3a3faa6b386f1fa1d6788b7f90ae59c3bd4fc7ca07cdbef7c1352c51e673ec27'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Excelente profesor, califica suave, explica super claro, no pierde mucho tiempo explicando cosas que luego no sirven, super buena gente y muy accesible. Ideal para aprender bien y pasar el curso con buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, '705a93960e861805900752c896c2e45778e74d7f30dddbc95fd256e74215111b'::TEXT, ARRAY[563]::BIGINT[]),
