    (519::BIGINT, 'Excelente profe, excelente persona. Comprensivo, califica normal.. en fin una teja!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, '363422edd892c9df287854e198a52fb8388e3125e599ac35f62f74c2a15b35bc'::TEXT, ARRAY[563, 605, 634]::BIGINT[]),
    (519::BIGINT, 'Excelente persona, gran profesional. Explica como ninguno, es una persona muy comprensiva, de verdad es un profesor excelente. Todas sus clases son de provecho y su trato es óptimo. De verdad vale la pena estudiar con él. Es muy pura vida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'ffc501a53e12dc838599402bc38cfad083fbabd5978525eb489de5ef6bcb61d9'::TEXT, ARRAY[563]::BIGINT[]),
    (519::BIGINT, 'Si tiene la oportunidad de meter con el no lo dude, el porcentaje de aprobación es super alto, le interesa que uno aprenda, y es super buena persona. califica muy bien y si uno lo convence cambia el quiz por tarea o de dia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-21T00:00:00+00:00'::TIMESTAMPTZ, '2a2389b66137b83854ca967cb556efd27c3a4cd39403bc796bbf27625ef6dc5d'::TEXT, ARRAY[634]::BIGINT[]),
    (519::BIGINT, 'No dude matricular con este profe! Es una teja de persona. Califica apropiadamente, explica con muchisima claridad y no hace muchos quizes ni tareas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-20T00:00:00+00:00'::TIMESTAMPTZ, '651c4637f6b8cf5252f9bd29b759a6d5c01c423e0b3893185c82c1a67f767f8e'::TEXT, ARRAY[634]::BIGINT[]),
