    (519::BIGINT, 'Está solo Norberto. Muy buen profe solo que algunas veces se acelera y uno se queda botado. Explica como para kinder y las veces que sea..además se jala unos chistes bien malos de la liga y saprissa...'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, '9a2b46394355a1e58b5d061fef8444e76af272591a7b9d2ef410b6649ed85d8c'::TEXT, ARRAY[634]::BIGINT[]),
