    (519::BIGINT, 'De los mejores profesores de matemáticas. Sus explicaciones hacen que las cosas parezcan sencillas. Excelente como persona, tiene empatía con el estudiante. Si tiene la oportunidad, no lo piense nada más meta el curso con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'e46b9fe875c544e591a0e58781544c3464a03af68ab00fef31617136c447d567'::TEXT, ARRAY[563, 2920]::BIGINT[]),
